SELECT e.id, coalesce((SELECT max(x.revision_no) FROM public.essay_revisions x WHERE x.essay_id = e.id), 0) + 1, 'rollback',
       e.title, e.snippet, e.content_json, e.status, $s$Restored from the snapshot taken before the lecture-notes removal$s$, null
  FROM public.essays e WHERE e.id = 'a26e639f-4bb5-43a2-8119-f77003148ec2';

-- due-from-government-underlift-vat-and-other-receivables
UPDATE public.essays
   SET content = $c$<p><strong>In brief</strong></p><ul><li><p>At a production sharing contractor, "due from the Government" collects three claims on the state, namely the underlift (oil the contractor was entitled to but did not lift), the DMO fee (what the state pays for crude the contractor must supply to the domestic market) and VAT the state reimburses.</p></li><li><p>An underlift is not revenue from contracts with customers under PSAK 115. Indonesian rules have the state pay a computed underlift in cash, which makes it a financial asset measured at the amount SKK Migas fixes, with expected credit losses; settled in barrels instead, it would be a non-financial item at cost.</p></li><li><p>On claims against the state the credit-loss allowance is tiny. Eligibility rulings and timing move the numbers, through write-offs and the current/non-current split. The "other receivables" lines need the general three-stage model, and in the case below one disputed item carries 85 percent of their allowance.</p></li></ul><hr><h2>The reported line fell 10.4 percent, and its name hides three claims with different accounting</h2><p>The balance sheet on this page reports due from the Government of 85,053 at 31 December 2024 against 94,887 a year earlier, in thousands, a fall of 9,834 or 10.4 percent. Other receivables, net, rose 2.2 percent to 28,830 (2023: 28,217), and other non-current receivables fell 10.2 percent to 3,106 (2023: 3,460). Together they are 0.39 percent of total assets at 31 December 2024 (116,989 / 30,303,898), and the face does not say what any of them contains.</p><p>This essay uses PT Hulu Energi Nusantara ("HEN"), an upstream contractor under production sharing contracts (PSCs) with SKK Migas, the government body that administers PSCs, reporting in USD under Indonesian SAK. HEN and every figure attached to it are constructed for illustration. HEN amounts are in USD thousand and volumes in thousand barrels (kbbl), except per-barrel prices in USD. "The state" below is the Government in the line's name. The case follows one block, PSC West, in which HEN holds 100 percent.</p><p>HEN's draft shows due from the Government of 34,075 at 31 December 2024, made of 24,000 for 300 kbbl of underlifted crude at USD 80 per barrel credited to revenue from contracts with customers, 675 of unpaid DMO fee and 9,400 of VAT reimbursement claims. In February 2025, before the March issue date, the auditor asks three questions. Can the underlift be revenue under PSAK 115? Do expected credit losses apply to a claim on the state? Why is a VAT claim more than a year old still current?</p><p>The governing claim of this essay is that each claim's settlement route, in barrels or in cash and within twelve months or later, decides its income line, its measurement basis, whether the credit-loss model applies and where it is presented.</p><p>This is a mechanism essay. Its verdict is that HEN's line falls only from 34,075 to 32,431.2, but revenue from contracts with customers falls by 24,000, and the settlement route alone is worth 10,500 of 2024 profit.</p><p>The standards are PSAK 115 (formerly 72, IFRS 15) for revenue, PSAK 109 (formerly 71, IFRS 9) and PSAK 232 (formerly 50, IAS 32) for financial assets, and PSAK 201 (formerly 1, IAS 1) for the current/non-current split.</p><h2>A PSC entitlement is a waterfall, and the contractor's barrels come after the state's share and the DMO</h2><p>A cost-recovery PSC divides each year's production in a fixed order, and the contractor's barrels come last. The terms below are simplified, with constructed percentages; each PSC sets its own.</p><ol><li><p>First tranche petroleum (FTP), here 20 percent of production, is taken before costs and split between the state and the contractor in the equity ratio.</p></li><li><p>Cost recovery gives the contractor its recoverable operating and capital costs in barrels, up to what remains after FTP.</p></li><li><p>The equity to be split is divided in a pre-tax ratio, 25 percent to HEN, which after the 40 percent combined PSC tax is 15 percent (25% × 60%).</p></li><li><p>The domestic market obligation (DMO) requires HEN to deliver crude equal to 25 percent of production multiplied by its 25 percent pre-tax share. The state takes these barrels and pays a DMO fee priced under rules set by the Minister of Energy, here 15 percent of the Indonesian Crude Price (ICP), the monthly government reference price.</p></li><li><p>Corporate and dividend tax is paid in cash on FTP share plus equity share less the net DMO, and does not reduce the barrels HEN lifts.</p></li></ol><p>PSC West produced 3,600 kbbl in 2024. To isolate volumes, take one annual ICP of USD 80.</p><blockquote><p>Gross production value = 3,600 kbbl × USD 80 = 288,000</p><p>FTP = 288,000 × 20% = 57,600; HEN 25% = 14,400; state 43,200</p><p>After FTP = 288,000 − 57,600 = 230,400</p><p>Cost recovery = 120,000 (2024 recoverable costs, all within the 230,400 available)</p><p>Equity to be split = 230,400 − 120,000 = 110,400; HEN 25% = 27,600; state 82,800</p><p>HEN's entitlement = 120,000 + 14,400 + 27,600 = 162,000, or 2,025 kbbl at USD 80</p><p>DMO volume = 3,600 × 25% × 25% = 225 kbbl, worth 18,000; DMO fee = 225 × USD 12 = 2,700</p><p>HEN's lifting entitlement = 2,025 − 225 = 1,800 kbbl</p><p>Taxable income = 14,400 + 27,600 − (18,000 − 2,700) = 26,700; tax at 40% = 10,680</p></blockquote><p>Cost recovery follows PSC rules (capital recovered on the contract's depreciation schedule, plus prior-year costs not yet recovered), so it differs from the accounting cost used later. HEN may lift and sell 1,800 kbbl for its own account. Lifting is crude sold or split at the custody transfer point, the meter where ownership is measured and passes, and the contractor owns its oil only from that point.</p><h2>Liftings follow tankers, so the contractor is overlifted or underlifted on almost every date</h2><p>Entitlement accrues at about 150 kbbl a month (1,800 / 12), while liftings come in cargoes of about 300 kbbl every two months. When cumulative liftings exceed cumulative entitlement HEN is overlifted and owes the state, a liability "due to the Government". When they fall short it is underlifted and the state owes it.</p><table style="min-width: 125px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Cargo</p></th><th colspan="1" rowspan="1"><p>Size</p></th><th colspan="1" rowspan="1"><p>Cumulative entitlement at month end</p></th><th colspan="1" rowspan="1"><p>Cumulative lifted</p></th><th colspan="1" rowspan="1"><p>Position</p></th></tr><tr><td colspan="1" rowspan="1"><p>15 Feb</p></td><td colspan="1" rowspan="1"><p>320</p></td><td colspan="1" rowspan="1"><p>300</p></td><td colspan="1" rowspan="1"><p>320</p></td><td colspan="1" rowspan="1"><p>overlifted 20</p></td></tr><tr><td colspan="1" rowspan="1"><p>10 Apr</p></td><td colspan="1" rowspan="1"><p>300</p></td><td colspan="1" rowspan="1"><p>600</p></td><td colspan="1" rowspan="1"><p>620</p></td><td colspan="1" rowspan="1"><p>overlifted 20</p></td></tr><tr><td colspan="1" rowspan="1"><p>5 Jun</p></td><td colspan="1" rowspan="1"><p>280</p></td><td colspan="1" rowspan="1"><p>900</p></td><td colspan="1" rowspan="1"><p>900</p></td><td colspan="1" rowspan="1"><p>balanced</p></td></tr><tr><td colspan="1" rowspan="1"><p>12 Aug</p></td><td colspan="1" rowspan="1"><p>310</p></td><td colspan="1" rowspan="1"><p>1,200</p></td><td colspan="1" rowspan="1"><p>1,210</p></td><td colspan="1" rowspan="1"><p>overlifted 10</p></td></tr><tr><td colspan="1" rowspan="1"><p>9 Oct</p></td><td colspan="1" rowspan="1"><p>290</p></td><td colspan="1" rowspan="1"><p>1,500</p></td><td colspan="1" rowspan="1"><p>1,500</p></td><td colspan="1" rowspan="1"><p>balanced</p></td></tr><tr><td colspan="1" rowspan="1"><p>27 Dec, cancelled</p></td><td colspan="1" rowspan="1"><p>(300)</p></td><td colspan="1" rowspan="1"><p>1,800</p></td><td colspan="1" rowspan="1"><p>1,500</p></td><td colspan="1" rowspan="1"><p>underlifted 300</p></td></tr></tbody></table><p>Small gaps close through the next nominations (the cargo slots each party requests). The December tanker was cancelled for weather on 23 December, and the terminal had no slot left in the 2024 programme, so the year ended with an underlift of 300 kbbl, a sixth of HEN's year.</p><p>PMK 139/2024, in force from 31 December 2024, now governs the settlement. SKK Migas calculates each party's lifting entitlement for each work area (contract area) and period; it bills an overlift to the contractor and pays an underlift promptly through the Ministry of Finance from the government's USD oil and gas account (Art. 12–13), and may offset it against amounts such as an overlift or an earlier DMO-fee overpayment (Art. 16). Claims already forwarded for payment before that date continue under the revoked PMK 118/2019 and 119/2019 (Art. 37). On 30 December 2024 SKK Migas confirmed in writing that the 300 kbbl would enter its 2024 calculation as an underlift. HEN expects payment in 2025, so the claim is current.</p><h2>PSAK 115 puts revenue on barrels transferred to customers, so the underlift is a claim and not a sale</h2><p>HEN's draft used the entitlement method, which books revenue on entitled barrels with a receivable for an underlift or a payable for an overlift; the sales (lifting) method books revenue on barrels sold. PSAK 115 recognises revenue when control of a good passes to a customer. In March 2019 the IFRS Interpretations Committee considered a joint operator whose output received differed from its entitlement, with the shortfall settled by later deliveries, and concluded that it recognises revenue only for output transferred to its customers. The state is not a joint operator under PSAK 111 (formerly 66, IFRS 11), so the decision applies to HEN by analogy, but the logic holds, since no customer has taken the 300 kbbl.</p><p>HEN treats the DMO delivery as a sale. The PSC obliges HEN to deliver the barrels, and the state takes them for a fee, which is a contract with a customer even at 15 percent of ICP. The 2,700 fee is revenue from contracts with customers, and the unpaid 675 is a trade receivable from the state.</p><blockquote><p>Revenue from contracts with customers = 1,500 kbbl × USD 80 + 2,700 = 120,000 + 2,700 = 122,700, against 146,700 in the draft</p><p>Reclassify the draft entry: Dr Revenue from contracts with customers 24,000 / Cr Other operating income, lifting imbalance 24,000</p></blockquote><p>The underlift claim, payable in cash, is a contractual right to receive cash, a financial asset under PSAK 232 and PSAK 109. HEN measures it at amortised cost (the amount expected, adjusted for credit losses, with interest at the effective rate, here nil for a claim due within months), starting from the amount SKK Migas will fix, 300 kbbl at the ICP used in its calculation, 24,000. Presenting the credit as other operating income rather than as revenue is HEN's judgment; an argument exists that a state paying for barrels it took is a customer.</p><h2>Settlement in barrels would change the measurement by 10,500 and remove the credit-loss allowance</h2><p>Had SKK Migas carried the 300 kbbl into HEN's 2025 liftings, the IFRIC fact pattern, HEN would hold a right to future oil, a non-financial item outside PSAK 109, with no credit-loss allowance. No standard covers it, so HEN would set a policy under PSAK 208 (formerly 25, IAS 8), either at cost as a deferral of production cost or at market as a right to product. HEN bears all of PSC West's costs, 91,125 of operating costs and depletion in 2024, but receives only its 2,025 kbbl of entitlement, DMO barrels included, so the cost per barrel spreads over those.</p><blockquote><p>Cost per entitled barrel = 91,125 / 2,025 = USD 45.00</p><p>Underlift at cost = 300 × 45.00 = 13,500, against 24,000 at the cash amount</p><p>Gross margin on the block, cash route = 122,700 + 24,000 − 91,125 = 55,575</p><p>Gross margin on the block, in kind at cost = 122,700 − (91,125 − 13,500) = 45,075</p></blockquote><p>The 10,500 gap is margin on barrels no customer has bought; in kind it waits for the 2025 sale, while in cash the state buys out HEN's right in 2024. The regulation and SKK Migas's letter put HEN on the cash route.</p><h2>VAT reimbursement fails on eligibility and timing, and the state's credit barely registers</h2><p>HEN's VAT claims lose value through rejected items and slow payment, not through default. Contractors were designated VAT collectors (<em>pemungut PPN</em>) under PMK 73/PMK.03/2010, so HEN withholds the VAT on a vendor's invoice and deposits it to the treasury itself. PMK 139 Art. 5 ties reimbursement to VAT already deposited, and Art. 3 keeps the earlier conditions, under which a claim may be made only after the state's share is received and is capped at the state share deposited (126,000 for HEN), or at the equity share alone (82,800) where the PSC excludes FTP. Neither cap binds. A September purchase of well services of 10,000 at the 11 percent rate in force in 2024 runs as follows.</p><blockquote><p>Purchase: Dr Production costs 10,000 / Dr VAT awaiting deposit 1,100 / Cr Trade payables 10,000 / Cr VAT collected payable 1,100</p><p>Deposit in October: Dr VAT collected payable 1,100 / Cr Cash 1,100; Dr Due from the Government, VAT reimbursement 1,100 / Cr VAT awaiting deposit 1,100</p></blockquote><p>HEN's open claims at 31 December 2024, by time since submission, are as follows.</p><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Age of claim</p></th><th colspan="1" rowspan="1"><p>Amount</p></th><th colspan="1" rowspan="1"><p>Status</p></th></tr><tr><td colspan="1" rowspan="1"><p>0–3 months</p></td><td colspan="1" rowspan="1"><p>3,400</p></td><td colspan="1" rowspan="1"><p>in review</p></td></tr><tr><td colspan="1" rowspan="1"><p>3–6 months</p></td><td colspan="1" rowspan="1"><p>2,500</p></td><td colspan="1" rowspan="1"><p>in review</p></td></tr><tr><td colspan="1" rowspan="1"><p>6–12 months</p></td><td colspan="1" rowspan="1"><p>1,900</p></td><td colspan="1" rowspan="1"><p>verified, awaiting payment</p></td></tr><tr><td colspan="1" rowspan="1"><p>Over 12 months</p></td><td colspan="1" rowspan="1"><p>1,600</p></td><td colspan="1" rowspan="1"><p>600 rejected; 1,000 resubmitted</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Total</strong></p></td><td colspan="1" rowspan="1"><p><strong>9,400</strong></p></td><td colspan="1" rowspan="1"><p></p></td></tr></tbody></table><p>On 14 November 2024 SKK Migas rejected 1,600 of 2023 claims. 600 was VAT on costs not chargeable as operating costs, which Art. 5(2)(c) excludes, so it was never a valid claim and goes to cost.</p><blockquote><p>Dr Production costs 600 / Cr Due from the Government, VAT reimbursement 600</p></blockquote><p>The other 1,000 was rejected for missing original tax invoices from one vendor. HEN obtained them and resubmitted on 2 December 2024, and a 2022 claim rejected on the same ground was paid in full after resubmission, about 20 months later. The right is intact, so HEN keeps 1,000 at amortised cost; with no interest and an effective rate of nil, the delay does not change the carrying amount. Payment is expected in 2026, so PSAK 201 moves it to other non-current receivables. Current VAT claims are 7,800 (3,400 + 2,500 + 1,900).</p><p>A refund created only by statute is not a financial asset, because PSAK 232 requires a contract; HEN's VAT right also rests on the PSC's reimbursement clause, so HEN treats it as within PSAK 109, a judgment that varies in practice.</p><p>PSAK 109 requires the simplified approach (a lifetime expected loss from the start) for trade receivables under PSAK 115, so it applies to the 675 DMO fee. Other financial assets follow the general approach. Each starts in stage 1, with a 12-month expected loss; moves to stage 2, a lifetime loss, on a significant increase in credit risk, presumed at 30 days past due; and to stage 3, lifetime loss with interest on the net amount, when credit-impaired, meaning a loss event such as default has occurred, presumed at 90 days past due. Both presumptions can be rebutted with evidence. HEN keeps the underlift and VAT claims in stage 1, because documentary review and resubmission say nothing about the state's capacity to pay. It uses a constructed default probability (the chance of default over the period) of 0.30 percent and a loss given default (the share not recovered after a default) of 45 percent; for claims due within a year, lifetime and 12-month probability coincide.</p><blockquote><p>Current, general approach = (24,000 + 7,800) × 0.30% × 45% = 42.9</p><p>Current, simplified approach = 675 × 0.30% × 45% = 0.9</p><p>Non-current VAT = 1,000 × 0.30% × 45% = 1.4</p><p>Total allowance on the state = 43.8 + 1.4 = 45.2, against 600 written off and 1,000 moved to non-current</p></blockquote><h2>Other receivables use the general three-stage model, and the "other" bucket is where disputed claims wait</h2><p>"Other receivables" holds one-off claims with no portfolio history to age against, so an item can sit there for years. HEN assesses each item at 31 December 2024 (probabilities and loss rates constructed).</p><table style="min-width: 125px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Item</p></th><th colspan="1" rowspan="1"><p>Gross</p></th><th colspan="1" rowspan="1"><p>Stage</p></th><th colspan="1" rowspan="1"><p>Basis</p></th><th colspan="1" rowspan="1"><p>Allowance</p></th></tr><tr><td colspan="1" rowspan="1"><p>Insurance claim for compressor damage, accepted 10 Dec 2024</p></td><td colspan="1" rowspan="1"><p>2,000</p></td><td colspan="1" rowspan="1"><p>1</p></td><td colspan="1" rowspan="1"><p>1% × 40%</p></td><td colspan="1" rowspan="1"><p>8</p></td></tr><tr><td colspan="1" rowspan="1"><p>Interest receivable on bank deposits</p></td><td colspan="1" rowspan="1"><p>300</p></td><td colspan="1" rowspan="1"><p>1</p></td><td colspan="1" rowspan="1"><p>negligible</p></td><td colspan="1" rowspan="1"><p>0</p></td></tr><tr><td colspan="1" rowspan="1"><p>Employee housing loans</p></td><td colspan="1" rowspan="1"><p>1,200</p></td><td colspan="1" rowspan="1"><p>1</p></td><td colspan="1" rowspan="1"><p>2% × 50%</p></td><td colspan="1" rowspan="1"><p>12</p></td></tr><tr><td colspan="1" rowspan="1"><p>Liquidated damages from a drilling contractor</p></td><td colspan="1" rowspan="1"><p>900</p></td><td colspan="1" rowspan="1"><p>2</p></td><td colspan="1" rowspan="1"><p>lifetime 30% × 60%</p></td><td colspan="1" rowspan="1"><p>162</p></td></tr><tr><td colspan="1" rowspan="1"><p>Farm-out settlement from a former partner</p></td><td colspan="1" rowspan="1"><p>1,500</p></td><td colspan="1" rowspan="1"><p>3</p></td><td colspan="1" rowspan="1"><p>expected recovery 450</p></td><td colspan="1" rowspan="1"><p>1,050</p></td></tr><tr><td colspan="1" rowspan="1"><p><strong>Total</strong></p></td><td colspan="1" rowspan="1"><p><strong>5,900</strong></p></td><td colspan="1" rowspan="1"><p></p></td><td colspan="1" rowspan="1"><p></p></td><td colspan="1" rowspan="1"><p><strong>1,232</strong></p></td></tr></tbody></table><p>Once the insurer accepted the claim and fixed its amount, HEN treats it as a receivable under PSAK 109. Liquidated damages are penalties a contract fixes for late performance; the drilling rig arrived 40 days late, the contractor's credit rating was cut on 5 November 2024, and the invoice is 75 days overdue, so a lifetime loss replaces a 12-month one. A farm-out is a transfer of part of a block interest to a partner, and the former partner disputed its final settlement in writing on 20 August 2024. It is 400 days overdue and credit-impaired. HEN filed for arbitration in October 2024, its counsel expects an award in 2026, and HEN estimates recovery of 450. That one item carries 85 percent of the allowance (1,050 / 1,232).</p><p>Classification follows when the cash is expected. The 450 arrives in 2026, and 800 of the employee loans fall due after December 2025, with 8 of their 12 allowance.</p><blockquote><p>Other receivables, net (current) = (5,900 − 1,500 − 800) − (1,232 − 1,050 − 8) = 3,600 − 174 = 3,426</p><p>Other non-current receivables = 450 + (800 − 8) + (1,000 − 1.4) = 450 + 792 + 998.6 = 2,240.6</p></blockquote><p>A flat "other receivables" balance, like the 2.2 percent change on this page, can mean steady turnover or the same claims carried forward. Only the note's ageing, its stage table and the stage 3 share of the allowance tell them apart.</p><h2>Corrected, HEN's due from the Government is 32,431.2, and the large correction sits in the income statement</h2><p>HEN's line at 31 December 2024 falls by 1,643.8, from the draft's 34,075 to 32,431.2.</p><blockquote><p>Draft = 24,000 + 675 + 9,400 = 34,075</p><p>Ineligible VAT written off = (600)</p><p>Resubmitted VAT moved to other non-current receivables = (1,000)</p><p>Credit-loss allowance, current = (43.8)</p><p>Corrected = 24,000 + 675 + 7,800 − 43.8 = 32,431.2</p></blockquote><p>Revenue from contracts with customers falls from 146,700 to 122,700, and the 24,000 moves to other operating income; gross margin on the block stays 55,575. The auditor's three questions get three answers. The underlift is a cash claim, not revenue; credit losses apply and total 45.2; and the old VAT claim was partly invalid and partly non-current. Had SKK Migas settled the underlift in barrels, the line would have been 21,963.6 and 2024 margin 10,500 lower. The 10.4 percent fall on this page could come from any of these routes, and only the note says which.</p><h3>Least-confident assertions</h3><ul><li><p>The PSC waterfall is simplified. FTP at 20 percent shared in the equity ratio, the 25 percent pre-tax split, the DMO volume and a fee at 15 percent of ICP are constructed; real PSCs differ, and real calculations use monthly ICP, which adds price imbalances to volume ones.</p></li><li><p>Small intra-year gaps closing through nominations, and the timing of SKK Migas's period calculation and payment, are stated from general knowledge; PMK 139 Art. 12–13 says "promptly" without a deadline. Whether SKK Migas ever carries a year-end underlift into the next year in kind was not checked.</p></li><li><p>Presenting the cash-settled underlift as other operating income, applying the 2019 joint-operator decision by analogy, and measuring an in-kind underlift at cost are the essay's judgments; Indonesian contractors' actual policies were not reached.</p></li><li><p>Treating the DMO delivery as a PSAK 115 sale and PSC VAT reimbursement as a contractual financial asset are judgments that vary in practice. HEN's status as a VAT collector rests on PMK 73/PMK.03/2010, revoked on 18 October 2024 by PMK 81/2024, whose collector provisions were not read.</p></li><li><p>PSAK 115, 109, 232, 201, 208 and 111 were not opened, so they are cited by subject, not paragraph. The 30-day and 90-day presumptions are from knowledge of IFRS 9.</p></li></ul><h2>References</h2><ol><li><p>PMK 139/2024 on payment of claims on the government in upstream oil and gas, in force 31 December 2024: Art. 1 (definitions), Art. 3–5 (VAT reimbursement conditions, caps, exclusions including Art. 5(2)(c)), Art. 12–13 (lifting calculation; overlift billed, underlift paid), Art. 16 (offsets), Art. 37 (transition). VERIFIED (web, JDIH Kemenkeu PDF, read in the independent recheck of 2026-10-09; the document page was opened by the author).</p></li><li><p>PMK 118/PMK.02/2019 on the DMO fee, overlifting and underlifting, consolidated with PMK 51/2023 (JDIH Kemenkeu consolidated text, compiled 21 March 2024), Art. 1–5 and 8. VERIFIED (web, PDF opened). Revoked by PMK 139/2024; still relevant under Art. 37.</p></li><li><p>PMK 119/PMK.02/2019 on VAT reimbursement for upstream contractors. VERIFIED (web, DDTC News, 28 August 2019, secondary source).</p></li><li><p>PMK 73/PMK.03/2010 designating PSC contractors as VAT collectors; revoked 18 October 2024 by PMK 81/2024. VERIFIED (web, BPK and JDIH Kemenkeu database entries; text not read).</p></li><li><p>EY, <em>IFRS Developments</em> Issue 149, "Sale of output by a joint operator" (May 2019), on the March 2019 IFRS Interpretations Committee agenda decision and the cost versus fair value measurement of imbalances. VERIFIED (web, ey.com, PDF opened).</p></li><li><p>Owner's study notes, "Inter 2 - Chapter 18 - Revenue Recognition.pdf" (Rumpun Akuntansi Keuangan), section A (five-step model, recognition when a performance obligation is satisfied). NOTES. Used for the revenue principle and voice; the notes do not cover PSC imbalances or expected credit losses.</p></li><li><p>Summary of the notes, <code>_referensi/rumpun-akuntansi-keuangan/02-inter-ta.md</code>, flag that the notes' impairment model predates the PSAK 109 three-stage model. NOTES.</p></li><li><p>PSAK 115 (IFRS 15). STANDARD — NOT VERIFIED.</p></li><li><p>PSAK 109 (IFRS 9), impairment: general and simplified approaches, stages, presumptions. STANDARD — NOT VERIFIED.</p></li><li><p>PSAK 232 (IAS 32), contractual basis of a financial asset. STANDARD — NOT VERIFIED.</p></li><li><p>PSAK 201 (IAS 1), PSAK 208 (IAS 8), PSAK 111 (IFRS 11). STANDARD — NOT VERIFIED.</p></li></ol>$c$,
       content_json = $j${"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"In brief","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"At a production sharing contractor, \"due from the Government\" collects three claims on the state, namely the underlift (oil the contractor was entitled to but did not lift), the DMO fee (what the state pays for crude the contractor must supply to the domestic market) and VAT the state reimburses.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"An underlift is not revenue from contracts with customers under PSAK 115. Indonesian rules have the state pay a computed underlift in cash, which makes it a financial asset measured at the amount SKK Migas fixes, with expected credit losses; settled in barrels instead, it would be a non-financial item at cost.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"On claims against the state the credit-loss allowance is tiny. Eligibility rulings and timing move the numbers, through write-offs and the current/non-current split. The \"other receivables\" lines need the general three-stage model, and in the case below one disputed item carries 85 percent of their allowance.","type":"text"}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"The reported line fell 10.4 percent, and its name hides three claims with different accounting","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The balance sheet on this page reports due from the Government of 85,053 at 31 December 2024 against 94,887 a year earlier, in thousands, a fall of 9,834 or 10.4 percent. Other receivables, net, rose 2.2 percent to 28,830 (2023: 28,217), and other non-current receivables fell 10.2 percent to 3,106 (2023: 3,460). Together they are 0.39 percent of total assets at 31 December 2024 (116,989 / 30,303,898), and the face does not say what any of them contains.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"This essay uses PT Hulu Energi Nusantara (\"HEN\"), an upstream contractor under production sharing contracts (PSCs) with SKK Migas, the government body that administers PSCs, reporting in USD under Indonesian SAK. HEN and every figure attached to it are constructed for illustration. HEN amounts are in USD thousand and volumes in thousand barrels (kbbl), except per-barrel prices in USD. \"The state\" below is the Government in the line's name. The case follows one block, PSC West, in which HEN holds 100 percent.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's draft shows due from the Government of 34,075 at 31 December 2024, made of 24,000 for 300 kbbl of underlifted crude at USD 80 per barrel credited to revenue from contracts with customers, 675 of unpaid DMO fee and 9,400 of VAT reimbursement claims. In February 2025, before the March issue date, the auditor asks three questions. Can the underlift be revenue under PSAK 115? Do expected credit losses apply to a claim on the state? Why is a VAT claim more than a year old still current?","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The governing claim of this essay is that each claim's settlement route, in barrels or in cash and within twelve months or later, decides its income line, its measurement basis, whether the credit-loss model applies and where it is presented.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"This is a mechanism essay. Its verdict is that HEN's line falls only from 34,075 to 32,431.2, but revenue from contracts with customers falls by 24,000, and the settlement route alone is worth 10,500 of 2024 profit.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The standards are PSAK 115 (formerly 72, IFRS 15) for revenue, PSAK 109 (formerly 71, IFRS 9) and PSAK 232 (formerly 50, IAS 32) for financial assets, and PSAK 201 (formerly 1, IAS 1) for the current/non-current split.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"A PSC entitlement is a waterfall, and the contractor's barrels come after the state's share and the DMO","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"A cost-recovery PSC divides each year's production in a fixed order, and the contractor's barrels come last. The terms below are simplified, with constructed percentages; each PSC sets its own.","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"First tranche petroleum (FTP), here 20 percent of production, is taken before costs and split between the state and the contractor in the equity ratio.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cost recovery gives the contractor its recoverable operating and capital costs in barrels, up to what remains after FTP.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The equity to be split is divided in a pre-tax ratio, 25 percent to HEN, which after the 40 percent combined PSC tax is 15 percent (25% × 60%).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The domestic market obligation (DMO) requires HEN to deliver crude equal to 25 percent of production multiplied by its 25 percent pre-tax share. The state takes these barrels and pays a DMO fee priced under rules set by the Minister of Energy, here 15 percent of the Indonesian Crude Price (ICP), the monthly government reference price.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Corporate and dividend tax is paid in cash on FTP share plus equity share less the net DMO, and does not reduce the barrels HEN lifts.","type":"text"}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSC West produced 3,600 kbbl in 2024. To isolate volumes, take one annual ICP of USD 80.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gross production value = 3,600 kbbl × USD 80 = 288,000","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"FTP = 288,000 × 20% = 57,600; HEN 25% = 14,400; state 43,200","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"After FTP = 288,000 − 57,600 = 230,400","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cost recovery = 120,000 (2024 recoverable costs, all within the 230,400 available)","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Equity to be split = 230,400 − 120,000 = 110,400; HEN 25% = 27,600; state 82,800","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's entitlement = 120,000 + 14,400 + 27,600 = 162,000, or 2,025 kbbl at USD 80","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"DMO volume = 3,600 × 25% × 25% = 225 kbbl, worth 18,000; DMO fee = 225 × USD 12 = 2,700","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's lifting entitlement = 2,025 − 225 = 1,800 kbbl","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Taxable income = 14,400 + 27,600 − (18,000 − 2,700) = 26,700; tax at 40% = 10,680","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cost recovery follows PSC rules (capital recovered on the contract's depreciation schedule, plus prior-year costs not yet recovered), so it differs from the accounting cost used later. HEN may lift and sell 1,800 kbbl for its own account. Lifting is crude sold or split at the custody transfer point, the meter where ownership is measured and passes, and the contractor owns its oil only from that point.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Liftings follow tankers, so the contractor is overlifted or underlifted on almost every date","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Entitlement accrues at about 150 kbbl a month (1,800 / 12), while liftings come in cargoes of about 300 kbbl every two months. When cumulative liftings exceed cumulative entitlement HEN is overlifted and owes the state, a liability \"due to the Government\". When they fall short it is underlifted and the state owes it.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cargo","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Size","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cumulative entitlement at month end","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cumulative lifted","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Position","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"15 Feb","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"320","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"300","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"320","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"overlifted 20","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"10 Apr","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"300","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"600","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"620","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"overlifted 20","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"5 Jun","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"280","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"900","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"900","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"balanced","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"12 Aug","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"310","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,200","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,210","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"overlifted 10","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"9 Oct","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"290","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,500","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,500","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"balanced","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"27 Dec, cancelled","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(300)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,800","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,500","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"underlifted 300","type":"text"}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Small gaps close through the next nominations (the cargo slots each party requests). The December tanker was cancelled for weather on 23 December, and the terminal had no slot left in the 2024 programme, so the year ended with an underlift of 300 kbbl, a sixth of HEN's year.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PMK 139/2024, in force from 31 December 2024, now governs the settlement. SKK Migas calculates each party's lifting entitlement for each work area (contract area) and period; it bills an overlift to the contractor and pays an underlift promptly through the Ministry of Finance from the government's USD oil and gas account (Art. 12–13), and may offset it against amounts such as an overlift or an earlier DMO-fee overpayment (Art. 16). Claims already forwarded for payment before that date continue under the revoked PMK 118/2019 and 119/2019 (Art. 37). On 30 December 2024 SKK Migas confirmed in writing that the 300 kbbl would enter its 2024 calculation as an underlift. HEN expects payment in 2025, so the claim is current.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"PSAK 115 puts revenue on barrels transferred to customers, so the underlift is a claim and not a sale","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's draft used the entitlement method, which books revenue on entitled barrels with a receivable for an underlift or a payable for an overlift; the sales (lifting) method books revenue on barrels sold. PSAK 115 recognises revenue when control of a good passes to a customer. In March 2019 the IFRS Interpretations Committee considered a joint operator whose output received differed from its entitlement, with the shortfall settled by later deliveries, and concluded that it recognises revenue only for output transferred to its customers. The state is not a joint operator under PSAK 111 (formerly 66, IFRS 11), so the decision applies to HEN by analogy, but the logic holds, since no customer has taken the 300 kbbl.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN treats the DMO delivery as a sale. The PSC obliges HEN to deliver the barrels, and the state takes them for a fee, which is a contract with a customer even at 15 percent of ICP. The 2,700 fee is revenue from contracts with customers, and the unpaid 675 is a trade receivable from the state.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Revenue from contracts with customers = 1,500 kbbl × USD 80 + 2,700 = 120,000 + 2,700 = 122,700, against 146,700 in the draft","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Reclassify the draft entry: Dr Revenue from contracts with customers 24,000 / Cr Other operating income, lifting imbalance 24,000","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The underlift claim, payable in cash, is a contractual right to receive cash, a financial asset under PSAK 232 and PSAK 109. HEN measures it at amortised cost (the amount expected, adjusted for credit losses, with interest at the effective rate, here nil for a claim due within months), starting from the amount SKK Migas will fix, 300 kbbl at the ICP used in its calculation, 24,000. Presenting the credit as other operating income rather than as revenue is HEN's judgment; an argument exists that a state paying for barrels it took is a customer.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Settlement in barrels would change the measurement by 10,500 and remove the credit-loss allowance","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Had SKK Migas carried the 300 kbbl into HEN's 2025 liftings, the IFRIC fact pattern, HEN would hold a right to future oil, a non-financial item outside PSAK 109, with no credit-loss allowance. No standard covers it, so HEN would set a policy under PSAK 208 (formerly 25, IAS 8), either at cost as a deferral of production cost or at market as a right to product. HEN bears all of PSC West's costs, 91,125 of operating costs and depletion in 2024, but receives only its 2,025 kbbl of entitlement, DMO barrels included, so the cost per barrel spreads over those.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Cost per entitled barrel = 91,125 / 2,025 = USD 45.00","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Underlift at cost = 300 × 45.00 = 13,500, against 24,000 at the cash amount","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gross margin on the block, cash route = 122,700 + 24,000 − 91,125 = 55,575","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gross margin on the block, in kind at cost = 122,700 − (91,125 − 13,500) = 45,075","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The 10,500 gap is margin on barrels no customer has bought; in kind it waits for the 2025 sale, while in cash the state buys out HEN's right in 2024. The regulation and SKK Migas's letter put HEN on the cash route.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"VAT reimbursement fails on eligibility and timing, and the state's credit barely registers","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's VAT claims lose value through rejected items and slow payment, not through default. Contractors were designated VAT collectors (","type":"text"},{"text":"pemungut PPN","type":"text","marks":[{"type":"italic"}]},{"text":") under PMK 73/PMK.03/2010, so HEN withholds the VAT on a vendor's invoice and deposits it to the treasury itself. PMK 139 Art. 5 ties reimbursement to VAT already deposited, and Art. 3 keeps the earlier conditions, under which a claim may be made only after the state's share is received and is capped at the state share deposited (126,000 for HEN), or at the equity share alone (82,800) where the PSC excludes FTP. Neither cap binds. A September purchase of well services of 10,000 at the 11 percent rate in force in 2024 runs as follows.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Purchase: Dr Production costs 10,000 / Dr VAT awaiting deposit 1,100 / Cr Trade payables 10,000 / Cr VAT collected payable 1,100","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Deposit in October: Dr VAT collected payable 1,100 / Cr Cash 1,100; Dr Due from the Government, VAT reimbursement 1,100 / Cr VAT awaiting deposit 1,100","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's open claims at 31 December 2024, by time since submission, are as follows.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Age of claim","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Amount","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Status","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0–3 months","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,400","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"in review","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3–6 months","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,500","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"in review","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"6–12 months","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,900","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"verified, awaiting payment","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Over 12 months","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,600","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"600 rejected; 1,000 resubmitted","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"9,400","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"On 14 November 2024 SKK Migas rejected 1,600 of 2023 claims. 600 was VAT on costs not chargeable as operating costs, which Art. 5(2)(c) excludes, so it was never a valid claim and goes to cost.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dr Production costs 600 / Cr Due from the Government, VAT reimbursement 600","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The other 1,000 was rejected for missing original tax invoices from one vendor. HEN obtained them and resubmitted on 2 December 2024, and a 2022 claim rejected on the same ground was paid in full after resubmission, about 20 months later. The right is intact, so HEN keeps 1,000 at amortised cost; with no interest and an effective rate of nil, the delay does not change the carrying amount. Payment is expected in 2026, so PSAK 201 moves it to other non-current receivables. Current VAT claims are 7,800 (3,400 + 2,500 + 1,900).","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"A refund created only by statute is not a financial asset, because PSAK 232 requires a contract; HEN's VAT right also rests on the PSC's reimbursement clause, so HEN treats it as within PSAK 109, a judgment that varies in practice.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 109 requires the simplified approach (a lifetime expected loss from the start) for trade receivables under PSAK 115, so it applies to the 675 DMO fee. Other financial assets follow the general approach. Each starts in stage 1, with a 12-month expected loss; moves to stage 2, a lifetime loss, on a significant increase in credit risk, presumed at 30 days past due; and to stage 3, lifetime loss with interest on the net amount, when credit-impaired, meaning a loss event such as default has occurred, presumed at 90 days past due. Both presumptions can be rebutted with evidence. HEN keeps the underlift and VAT claims in stage 1, because documentary review and resubmission say nothing about the state's capacity to pay. It uses a constructed default probability (the chance of default over the period) of 0.30 percent and a loss given default (the share not recovered after a default) of 45 percent; for claims due within a year, lifetime and 12-month probability coincide.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Current, general approach = (24,000 + 7,800) × 0.30% × 45% = 42.9","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Current, simplified approach = 675 × 0.30% × 45% = 0.9","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Non-current VAT = 1,000 × 0.30% × 45% = 1.4","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total allowance on the state = 43.8 + 1.4 = 45.2, against 600 written off and 1,000 moved to non-current","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Other receivables use the general three-stage model, and the \"other\" bucket is where disputed claims wait","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"\"Other receivables\" holds one-off claims with no portfolio history to age against, so an item can sit there for years. HEN assesses each item at 31 December 2024 (probabilities and loss rates constructed).","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Item","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Gross","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Stage","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Basis","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Allowance","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Insurance claim for compressor damage, accepted 10 Dec 2024","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,000","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1% × 40%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"8","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Interest receivable on bank deposits","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"300","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"negligible","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"0","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Employee housing loans","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,200","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2% × 50%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"12","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Liquidated damages from a drilling contractor","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"900","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"lifetime 30% × 60%","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"162","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Farm-out settlement from a former partner","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,500","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"expected recovery 450","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,050","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"5,900","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"1,232","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Once the insurer accepted the claim and fixed its amount, HEN treats it as a receivable under PSAK 109. Liquidated damages are penalties a contract fixes for late performance; the drilling rig arrived 40 days late, the contractor's credit rating was cut on 5 November 2024, and the invoice is 75 days overdue, so a lifetime loss replaces a 12-month one. A farm-out is a transfer of part of a block interest to a partner, and the former partner disputed its final settlement in writing on 20 August 2024. It is 400 days overdue and credit-impaired. HEN filed for arbitration in October 2024, its counsel expects an award in 2026, and HEN estimates recovery of 450. That one item carries 85 percent of the allowance (1,050 / 1,232).","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Classification follows when the cash is expected. The 450 arrives in 2026, and 800 of the employee loans fall due after December 2025, with 8 of their 12 allowance.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Other receivables, net (current) = (5,900 − 1,500 − 800) − (1,232 − 1,050 − 8) = 3,600 − 174 = 3,426","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Other non-current receivables = 450 + (800 − 8) + (1,000 − 1.4) = 450 + 792 + 998.6 = 2,240.6","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"A flat \"other receivables\" balance, like the 2.2 percent change on this page, can mean steady turnover or the same claims carried forward. Only the note's ageing, its stage table and the stage 3 share of the allowance tell them apart.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"Corrected, HEN's due from the Government is 32,431.2, and the large correction sits in the income statement","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"HEN's line at 31 December 2024 falls by 1,643.8, from the draft's 34,075 to 32,431.2.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Draft = 24,000 + 675 + 9,400 = 34,075","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Ineligible VAT written off = (600)","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Resubmitted VAT moved to other non-current receivables = (1,000)","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Credit-loss allowance, current = (43.8)","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Corrected = 24,000 + 675 + 7,800 − 43.8 = 32,431.2","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Revenue from contracts with customers falls from 146,700 to 122,700, and the 24,000 moves to other operating income; gross margin on the block stays 55,575. The auditor's three questions get three answers. The underlift is a cash claim, not revenue; credit losses apply and total 45.2; and the old VAT claim was partly invalid and partly non-current. Had SKK Migas settled the underlift in barrels, the line would have been 21,963.6 and 2024 margin 10,500 lower. The 10.4 percent fall on this page could come from any of these routes, and only the note says which.","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":null},"content":[{"text":"Least-confident assertions","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The PSC waterfall is simplified. FTP at 20 percent shared in the equity ratio, the 25 percent pre-tax split, the DMO volume and a fee at 15 percent of ICP are constructed; real PSCs differ, and real calculations use monthly ICP, which adds price imbalances to volume ones.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Small intra-year gaps closing through nominations, and the timing of SKK Migas's period calculation and payment, are stated from general knowledge; PMK 139 Art. 12–13 says \"promptly\" without a deadline. Whether SKK Migas ever carries a year-end underlift into the next year in kind was not checked.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Presenting the cash-settled underlift as other operating income, applying the 2019 joint-operator decision by analogy, and measuring an in-kind underlift at cost are the essay's judgments; Indonesian contractors' actual policies were not reached.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Treating the DMO delivery as a PSAK 115 sale and PSC VAT reimbursement as a contractual financial asset are judgments that vary in practice. HEN's status as a VAT collector rests on PMK 73/PMK.03/2010, revoked on 18 October 2024 by PMK 81/2024, whose collector provisions were not read.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 115, 109, 232, 201, 208 and 111 were not opened, so they are cited by subject, not paragraph. The 30-day and 90-day presumptions are from knowledge of IFRS 9.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"References","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PMK 139/2024 on payment of claims on the government in upstream oil and gas, in force 31 December 2024: Art. 1 (definitions), Art. 3–5 (VAT reimbursement conditions, caps, exclusions including Art. 5(2)(c)), Art. 12–13 (lifting calculation; overlift billed, underlift paid), Art. 16 (offsets), Art. 37 (transition). VERIFIED (web, JDIH Kemenkeu PDF, read in the independent recheck of 2026-10-09; the document page was opened by the author).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PMK 118/PMK.02/2019 on the DMO fee, overlifting and underlifting, consolidated with PMK 51/2023 (JDIH Kemenkeu consolidated text, compiled 21 March 2024), Art. 1–5 and 8. VERIFIED (web, PDF opened). Revoked by PMK 139/2024; still relevant under Art. 37.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PMK 119/PMK.02/2019 on VAT reimbursement for upstream contractors. VERIFIED (web, DDTC News, 28 August 2019, secondary source).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PMK 73/PMK.03/2010 designating PSC contractors as VAT collectors; revoked 18 October 2024 by PMK 81/2024. VERIFIED (web, BPK and JDIH Kemenkeu database entries; text not read).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"EY, ","type":"text"},{"text":"IFRS Developments","type":"text","marks":[{"type":"italic"}]},{"text":" Issue 149, \"Sale of output by a joint operator\" (May 2019), on the March 2019 IFRS Interpretations Committee agenda decision and the cost versus fair value measurement of imbalances. VERIFIED (web, ey.com, PDF opened).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Owner's study notes, \"Inter 2 - Chapter 18 - Revenue Recognition.pdf\" (Rumpun Akuntansi Keuangan), section A (five-step model, recognition when a performance obligation is satisfied). NOTES. Used for the revenue principle and voice; the notes do not cover PSC imbalances or expected credit losses.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Summary of the notes, ","type":"text"},{"text":"_referensi/rumpun-akuntansi-keuangan/02-inter-ta.md","type":"text","marks":[{"type":"code"}]},{"text":", flag that the notes' impairment model predates the PSAK 109 three-stage model. NOTES.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 115 (IFRS 15). STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 109 (IFRS 9), impairment: general and simplified approaches, stages, presumptions. STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 232 (IAS 32), contractual basis of a financial asset. STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 201 (IAS 1), PSAK 208 (IAS 8), PSAK 111 (IFRS 11). STANDARD — NOT VERIFIED.","type":"text"}]}]}]}]}$j$::jsonb,
       presentation = $p${"deck":"Underlifting, the DMO fee and VAT reimbursement at a PSC contractor, and why the 'other' lines need the general credit-loss model","genre":null,"author_bio":null,"references":[],"hero_caption":null,"key_takeaways":["At a production sharing contractor, \"due from the Government\" collects three claims on the state, namely the underlift (oil the contractor was entitled to but did not lift), the DMO fee (what the state pays for crude the contractor must supply to the domestic market) and VAT the state reimburses.","An underlift is not revenue from contracts with customers under PSAK 115. Indonesian rules have the state pay a computed underlift in cash, which makes it a financial asset measured at the amount SKK Migas fixes, with expected credit losses; settled in barrels instead, it would be a non-financial item at cost.","On claims against the state the credit-loss allowance is tiny. Eligibility rulings and timing move the numbers, through write-offs and the current/non-current split. The \"other receivables\" lines need the general three-stage model, and in the case below one disputed item carries 85 percent of their allowance."],"revision_note":null}$p$::jsonb,
       updated_at = now()
 WHERE id = 'd95a7c88-509d-47ba-9b23-a55a919124af';
INSERT INTO public.essay_revisions (essay_id, revision_no, change_type, title, snippet, content_json, status, change_summary, changed_by)
SELECT e.id, coalesce((SELECT max(x.revision_no) FROM public.essay_revisions x WHERE x.essay_id = e.id), 0) + 1, 'rollback',
       e.title, e.snippet, e.content_json, e.status, $s$Restored from the snapshot taken before the lecture-notes removal$s$, null
  FROM public.essays e WHERE e.id = 'd95a7c88-509d-47ba-9b23-a55a919124af';

DO $chk$ BEGIN
  IF (SELECT count(*) FROM public.essays WHERE id IN ('8e26845c-467c-4c83-b593-a0c647e354be', '4af0724c-712f-4fa7-8cff-9e640cf00627', 'a26e639f-4bb5-43a2-8119-f77003148ec2', 'd95a7c88-509d-47ba-9b23-a55a919124af') AND updated_at = now()) <> 4 THEN
    RAISE EXCEPTION 'Not written: an essay in this part was changed after the snapshot. Nothing in this part was saved.';
  END IF;
END $chk$;
COMMIT;
